import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] p = new double[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        double[][] C = new double[22][22];
        double[] coef = new double[22];
        double[] sum_mask = new double[1 << 20];
        int[] size_mask = new int[1 << 20];

        // Compute binomial coefficients
        C[0][0] = 1.0;
        for (int i = 1; i <= n; i++) {
            C[i][0] = 1.0;
            for (int j = 1; j <= i; j++) {
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }

        // Precompute mask sizes and sums
        int totalMasks = 1 << n;
        for (int m = 0; m < totalMasks; m++) {
            size_mask[m] = 0;
            sum_mask[m] = 0.0;
            for (int j = 0; j < n; j++) {
                if (((m >> j) & 1) == 1) {
                    size_mask[m]++;
                    sum_mask[m] += p[j];
                }
            }
        }

        // Compute coefficients
        for (int i = k - 1; i >= 0; i--) {
            coef[i] = 1.0 - coef[i];
            for (int j = 1; i - j >= 0; j++) {
                coef[i - j] += C[n - 1 - i + j][j] * coef[i];
            }
        }

        // Calculate and output results
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++) {
            double answer = 0.0;
            if (p[i] > 0.005) {
                for (int mask = 0; mask < totalMasks; mask++) {
                    if (((mask >> i) & 1) == 1) continue;
                    if (size_mask[mask] >= k) continue;
                    if (1 - sum_mask[mask] != 0) {
                        answer += coef[size_mask[mask]] / (1 - sum_mask[mask]);
                    }
                }
            }
            output.append(String.format("%.12f ", p[i] * answer));
        }
        System.out.println(output.toString().trim());
        sc.close();
    }
}
